<?php require __DIR__.'/inc/header.php';$title='Contact Requests';$pdo=db();if(is_post()){verify_csrf();$pdo->prepare('UPDATE contact_requests SET status=?,notes=?,handled_at=CURRENT_TIMESTAMP WHERE id=?')->execute([post('status','in_progress'),post('notes',''),(int)post('id')]);flash('success','Contact request updated.');redirect('/admin/contacts.php');}$rows=$pdo->query('SELECT * FROM contact_requests ORDER BY id DESC')->fetchAll();?><div class="bg-white border rounded-2xl overflow-hidden soft"><div class="p-5 font-black">Inbox</div><div class="overflow-x-auto"><table class="w-full text-sm"><thead class="bg-slate-50"><tr><th class="p-3 text-left">Name</th><th class="p-3 text-left">Subject</th><th class="p-3 text-left">Message</th><th class="p-3">Status</th></tr></thead><tbody><?php foreach($rows as $r):?><tr class="border-t align-top"><td class="p-3"><b><?=e($r['name'])?></b><div class="text-xs text-slate-400"><?=e($r['email'])?></div><div class="text-xs text-slate-400"><?=e($r['phone'])?></div></td><td class="p-3 font-bold"><?=e($r['subject'])?></td><td class="p-3 max-w-xl"><?=e($r['message'])?></td><td class="p-3"><form method="post" class="space-y-2"><?=csrf_input()?><input type="hidden" name="id" value="<?=$r['id']?>"><select name="status" class="rounded-lg border-slate-200 text-xs"><option>new</option><option>in_progress</option><option>resolved</option><option>spam</option></select><textarea name="notes" placeholder="Internal notes" class="w-40 rounded-lg border-slate-200 text-xs"></textarea><button class="px-3 py-2 rounded-lg bg-slate-950 text-white text-xs">Save</button></form></td></tr><?php endforeach;?></tbody></table></div></div><?php require __DIR__.'/inc/footer.php'; ?>
